static resource res[LIMIT];static draw ds[LIMIT];static int nr,nd,np,nv;static rect free_rect[LIMIT*2];static int nf;static GLuint pages[LIMIT],buffer,fb;static float bg[3];static int priority,depth;
static const char *vs="#version 100\nattribute vec3 a_position;attribute vec4 a_colour;attribute vec3 a_uvq;uniform mat4 u_projection;varying mediump vec4 v_colour;varying highp vec3 v_uvq;void main(){gl_Position=u_projection*vec4(a_position,1.0);v_colour=a_colour;v_uvq=a_uvq;}";
static const char *avs="#version 300 es\nprecision highp float;in vec3 a_position;in vec4 a_colour;in vec3 a_uvq;in vec4 a_region;uniform mat4 u_projection;out mediump vec4 v_colour;out highp vec3 v_uvq;out highp float v_layer;void main(){gl_Position=u_projection*vec4(a_position,1.0);v_colour=a_colour;v_uvq=a_uvq;v_layer=a_region.x;}";
static const char *fs="#version 100\nprecision highp float;uniform sampler2D u_texture;uniform bool u_priority;varying mediump vec4 v_colour;varying highp vec3 v_uvq;void main(){vec2 uv=v_uvq.xy/v_uvq.z;vec4 texel=texture2D(u_texture,uv);if(texel.a==0.0)discard;vec4 c=v_colour*texel;gl_FragColor=u_priority?vec4(c.rgb,v_colour.a):c;}";
static const char *afs="#version 300 es\nprecision highp float;uniform lowp sampler2DArray u_texture;uniform bool u_priority;in mediump vec4 v_colour;in highp vec3 v_uvq;in highp float v_layer;out vec4 output_colour;void main(){vec2 uv=v_uvq.xy/v_uvq.z;vec4 texel=textureLod(u_texture,vec3(uv,v_layer),0.0);if(texel.a==0.0)discard;vec4 c=v_colour*texel;output_colour=u_priority?vec4(c.rgb,v_colour.a):c;}";
static const char *affs="#version 100\nprecision highp float;uniform sampler2D u_texture;uniform bool u_priority;varying mediump vec4 v_colour;varying highp vec3 v_uvq;varying highp vec4 v_region;void main(){vec2 uv=v_uvq.xy/v_uvq.z;vec4 r=floor(v_region+0.5);vec2 t=clamp(uv*r.zw,vec2(0.5),r.zw-0.5);vec4 texel=texture2D(u_texture,(r.xy+t)/2048.0);if(texel.a==0.0)discard;vec4 c=v_colour*texel;gl_FragColor=u_priority?vec4(c.rgb,v_colour.a):c;}";
static GLuint program(const char *v,const char *f){GLuint p=glCreateProgram();const char *s[2]={v,f};for(int i=0;i<2;i++){GLuint q=glCreateShader(i?GL_FRAGMENT_SHADER:GL_VERTEX_SHADER);glShaderSource(q,1,s+i,NULL);glCompileShader(q);GLint ok;glGetShaderiv(q,GL_COMPILE_STATUS,&ok);if(!ok){char log[4096];glGetShaderInfoLog(q,sizeof log,0,log);fprintf(stderr,"%s\n",log);exit(2);}glAttachShader(p,q);glDeleteShader(q);}const char *attrs[]={"a_position","a_colour","a_uvq","a_region"};for(int i=0;i<4;i++)glBindAttribLocation(p,i,attrs[i]);glLinkProgram(p);GLint ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);CHECK(ok);return p;}
static GLuint texture(int w,int h,const void *pixels){GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,pixels);return t;}
static double now(clockid_t id){struct timespec t;clock_gettime(id,&t);return t.tv_sec+t.tv_nsec*1e-9;}
static void load(const char *dir){char path[1024];snprintf(path,sizeof path,"%s/scene.meta",dir);FILE *f=fopen(path,"r");CHECK(f&&fscanf(f,"%f %f %f %d %d",bg,bg+1,bg+2,&priority,&depth)==5);fclose(f);snprintf(path,sizeof path,"%s/draws.bin",dir);f=fopen(path,"rb");CHECK(f);uint32_t h[6];while(fread(h,4,6,f)==6){CHECK(nd<LIMIT&&h[0]<LIMIT);draw *d=ds+nd++;d->tex=h[0];d->count=h[1];CHECK(d->count<=60000);memcpy(d->scissor,h+2,16);d->first=nv;nv+=d->count;d->v=malloc(d->count*sizeof(vertex));CHECK(d->v&&fread(d->v,sizeof(vertex),d->count,f)==d->count);if((int)d->tex>=nr)nr=d->tex+1;}CHECK(feof(f));fclose(f);for(int i=0;i<nr;i++){snprintf(path,sizeof path,"%s/texture-%d.rgba",dir,i);f=fopen(path,"rb");CHECK(f&&fscanf(f,"%d %d",&res[i].w,&res[i].h)==2);fgetc(f);resource *r=res+i;CHECK(r->w>0&&r->w<=1025&&r->h>0&&r->h<=1025);r->rgba=malloc((size_t)r->w*r->h*4);CHECK(r->rgba&&fread(r->rgba,4,(size_t)r->w*r->h,f)==(size_t)r->w*r->h);fclose(f);}}
static int cmp_resource(const void *a,const void *b){int x=*(const int*)a,y=*(const int*)b;return res[y].w*res[y].h-res[x].w*res[x].h;}
static void pack(void){int widths[LIMIT]={0},heights[LIMIT]={0},layers[LIMIT]={0};size_t payload=0;GLint maxlayers;glGetIntegerv(GL_MAX_ARRAY_TEXTURE_LAYERS,&maxlayers);int cohort=0;const char *setting=getenv("RR_ARRAY_COHORT_LAYERS");if(setting){cohort=atoi(setting);CHECK(cohort>0&&cohort<=maxlayers);maxlayers=cohort;}size_t allocated=0;for(int i=0;i<nr;i++){resource *r=res+i;int group=0;for(;group<np;group++)if(widths[group]==r->w&&heights[group]==r->h&&layers[group]<maxlayers)break;if(group==np){widths[np]=r->w;heights[np]=r->h;np++;}r->page=group;r->x=layers[group]++;r->y=0;payload+=(size_t)r->w*r->h*4;}
 for(int p=0;p<np;p++){glGenTextures(1,pages+p);glBindTexture(GL_TEXTURE_2D_ARRAY,pages[p]);glTexParameteri(GL_TEXTURE_2D_ARRAY,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D_ARRAY,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D_ARRAY,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D_ARRAY,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);int capacity=cohort?cohort:layers[p];allocated+=(size_t)widths[p]*heights[p]*capacity*4;glTexImage3D(GL_TEXTURE_2D_ARRAY,0,GL_RGBA8,widths[p],heights[p],capacity,0,GL_RGBA,GL_UNSIGNED_BYTE,NULL);}
 for(int i=0;i<nr;i++){resource *r=res+i;glBindTexture(GL_TEXTURE_2D_ARRAY,pages[r->page]);glTexSubImage3D(GL_TEXTURE_2D_ARRAY,0,0,0,r->x,r->w,r->h,1,GL_RGBA,GL_UNSIGNED_BYTE,r->rgba);r->tex=texture(r->w,r->h,r->rgba);}printf("resources=%d draws=%d vertices=%d arrays=%d payload=%zu array_bytes=%zu occupancy=%.6f cohort=%d\n",nr,nd,nv,np,payload,allocated,(double)payload/allocated,cohort);
}
static int degenerate(const draw *d){for(unsigned j=0;j<d->count;j+=3){const float *a=d->v[j].p,*b=d->v[j+1].p,*c=d->v[j+2].p;double area=((double)b[0]-a[0])*((double)c[1]-a[1])-((double)c[0]-a[0])*((double)b[1]-a[1]);if(area==0)return 1;}return 0;}
static int group_cmp(const void *a,const void *b){const draw *x=a,*y=b;int d=res[x->tex].page-res[y->tex].page;if(d)return d;for(int i=0;i<4;i++){d=x->scissor[i]-y->scissor[i];if(d)return d;}return (x->v[0].p[2]>y->v[0].p[2])-(x->v[0].p[2]<y->v[0].p[2]);}
static void depth_gate(void){CHECK(priority&&(depth==16||depth==24));float zs[60000];int n=0;for(int i=0;i<nd;i++)for(unsigned j=0;j<ds[i].count;j++){float z=ds[i].v[j].p[2];int found=0;for(int k=0;k<n;k++)if(zs[k]==z){found=1;break;}if(!found)zs[n++]=z;}double margin=1e9;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){double q=fabs((double)zs[i]-zs[j])*65535/2;if(q<margin)margin=q;}printf("DEPTH unique=%d minimum_separation_lsb=%.6f\n",n,margin);CHECK(margin>2);}
static unsigned submit(GLuint p,int mode,int affine,unsigned char *pixels,double *cpu,double *wall){draw order[LIMIT];memcpy(order,ds,nd*sizeof(draw));if(mode==3)qsort(order,nd,sizeof(draw),group_cmp);int cursor=0;for(int i=0;i<nd;i++){order[i].first=cursor;cursor+=order[i].count;}vertex *v=malloc(nv*sizeof(vertex));av *a=malloc(nv*sizeof(av));CHECK(v&&a);for(int i=0;i<nd;i++){draw *d=order+i;resource *r=res+d->tex;memcpy(v+d->first,d->v,d->count*sizeof(vertex));for(unsigned j=0;j<d->count;j++){a[d->first+j].v=d->v[j];float *region=a[d->first+j].region;region[0]=r->x;region[1]=r->y;region[2]=r->w;region[3]=r->h;}}
 double start=now(CLOCK_MONOTONIC),begin=now(CLOCK_THREAD_CPUTIME_ID);glBindFramebuffer(GL_FRAMEBUFFER,fb);glViewport(0,0,640,480);glDisable(GL_CULL_FACE);glDisable(GL_SCISSOR_TEST);if(priority)glDisable(GL_BLEND);else {glEnable(GL_BLEND);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);}glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LEQUAL);glDepthMask(GL_TRUE);glClearDepthf(1);glClearColor(bg[0],bg[1],bg[2],priority?0:1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glEnable(GL_SCISSOR_TEST);glUseProgram(p);const float matrix[16]={2.f/640,0,0,0,0,-2.f/480,0,0,0,0,1,0,-1,1,0,1};glUniformMatrix4fv(glGetUniformLocation(p,"u_projection"),1,GL_FALSE,matrix);glUniform1i(glGetUniformLocation(p,"u_priority"),priority);glUniform1i(glGetUniformLocation(p,"u_texture"),0);glActiveTexture(GL_TEXTURE0);glBindBuffer(GL_ARRAY_BUFFER,buffer);glBufferData(GL_ARRAY_BUFFER,nv*(mode?sizeof(av):sizeof(vertex)),mode?(void*)a:(void*)v,GL_STREAM_DRAW);int stride=mode?sizeof(av):sizeof(vertex);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,stride,(void*)0);glVertexAttribPointer(1,4,GL_FLOAT,GL_FALSE,stride,(void*)12);glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,stride,(void*)28);for(int i=0;i<3;i++)glEnableVertexAttribArray(i);if(mode){glVertexAttribPointer(3,4,GL_FLOAT,GL_FALSE,stride,(void*)40);glEnableVertexAttribArray(3);}else glDisableVertexAttribArray(3);
 unsigned draws=0;for(int i=0;i<nd;){draw *d=order+i;int end=i+1,count=d->count;if(mode>=2 && !degenerate(d))while(end<nd&&!degenerate(order+end)&&res[order[end].tex].page==res[d->tex].page&&!memcmp(order[end].scissor,d->scissor,16)){count+=order[end++].count;}glScissor(d->scissor[0],d->scissor[1],d->scissor[2],d->scissor[3]);glBindTexture(mode?GL_TEXTURE_2D_ARRAY:GL_TEXTURE_2D,mode?pages[res[d->tex].page]:res[d->tex].tex);glDrawArrays(GL_TRIANGLES,d->first,count);draws++;i=end;}*cpu=now(CLOCK_THREAD_CPUTIME_ID)-begin;glFinish();*wall=now(CLOCK_MONOTONIC)-start;if(pixels)glReadPixels(0,0,640,480,GL_RGBA,GL_UNSIGNED_BYTE,pixels);CHECK(glGetError()==GL_NO_ERROR);free(v);free(a);return draws;}
static unsigned compare(const char *label,unsigned char *a,unsigned char *b){unsigned n=0;for(int i=0;i<640*480;i++)n+=memcmp(a+i*4,b+i*4,4)!=0;printf("%s differing_pixels=%u\n",label,n);FILE *f=fopen(label,"wb");CHECK(f);fwrite(b,4,640*480,f);fclose(f);return n;}
int main(int argc,char **argv){CHECK(argc==2);CHECK(!SDL_Init(SDL_INIT_VIDEO));SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_ES);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,2);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,0);SDL_Window *w=SDL_CreateWindow("atlas frozen",0,0,640,480,SDL_WINDOW_OPENGL);CHECK(w);CHECK(SDL_GL_CreateContext(w));SDL_GL_SetSwapInterval(0);printf("GPU=%s\n",glGetString(GL_RENDERER));load(argv[1]);pack();GLuint target=texture(640,480,NULL),depthbuf;glGenFramebuffers(1,&fb);glBindFramebuffer(GL_FRAMEBUFFER,fb);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,target,0);glGenRenderbuffers(1,&depthbuf);glBindRenderbuffer(GL_RENDERBUFFER,depthbuf);glRenderbufferStorage(GL_RENDERBUFFER,depth==16?GL_DEPTH_COMPONENT16:GL_DEPTH_COMPONENT24_OES,640,480);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depthbuf);CHECK(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE);glGenBuffers(1,&buffer);GLuint ps[3]={program(vs,fs),program(avs,afs),program(avs,afs)};unsigned char *base=malloc(640*480*4),*candidate=malloc(640*480*4),*reference=malloc(640*480*4);char path[1024];snprintf(path,sizeof path,"%s/reference.rgba",argv[1]);FILE *f=fopen(path,"rb");CHECK(f&&fread(reference,4,640*480,f)==640*480);fclose(f);double cpu,wall;submit(ps[0],0,0,base,&cpu,&wall);unsigned fidelity=compare("baseline.rgba",reference,base);if(strstr((const char*)glGetString(GL_RENDERER),"Mali"))CHECK(!fidelity);for(int shader=1;shader<=1;shader++)for(int mode=1;mode<=2;mode++){unsigned draws=submit(ps[shader],mode,shader==2,candidate,&cpu,&wall);char label[80];snprintf(label,sizeof label,"%s-%s.rgba",shader==1?"array":"unused",mode==1?"ordered":"adjacent");unsigned diff=compare(label,base,candidate);printf("MODE shader=%d mode=%d draws=%u cpu_ms=%.6f finish_wall_ms=%.6f\n",shader,mode,draws,cpu*1000,wall*1000);CHECK(!diff);}
 depth_gate();submit(ps[1],3,0,candidate,&cpu,&wall);CHECK(!compare("opaque-grouped.rgba",base,candidate));
 for(int warm=0;warm<3;warm++)for(int mode=0;mode<4;mode++)submit(ps[mode?1:0],mode,0,NULL,&cpu,&wall);
 for(int sample=0;sample<20;sample++)for(int step=0;step<4;step++){int mode=(step+sample)%4;unsigned draws=submit(ps[mode?1:0],mode,0,NULL,&cpu,&wall);printf("TIMING sample=%d mode=%d draws=%u cpu_ms=%.6f finish_wall_ms=%.6f\n",sample,mode,draws,cpu*1000,wall*1000);}return 0;}
